mapper.update:
UPDATE reading_subscription_plan
SET status=#{status}, version=version+1
WHERE id=#{planId} AND version=#{expectedVersion}

mapper.select:
SELECT id FROM user_reading_subscription
WHERE status='ACTIVE' AND next_grant_at<=#{now}
  AND (end_at IS NULL OR next_grant_at<end_at)
ORDER BY next_grant_at ASC, id ASC LIMIT #{limit}
